<?php require __DIR__.'/app/bootstrap.php';$token=$_GET['token']??'';$stmt=$pdo->prepare("SELECT u.*,ss.next_service_date,ss.next_service_meter,ss.status service_status FROM units u LEFT JOIN service_schedules ss ON ss.unit_id=u.id WHERE u.qr_token=?");$stmt->execute([$token]);$u=$stmt->fetch();if(!$u){http_response_code(404);exit('Unit tidak ditemukan.');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($u['unit_code'])?></title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="public-card"><h1><?=e($u['unit_code'])?></h1><h3><?=e($u['unit_name'])?></h3><p>Lokasi: <?=e($u['location'])?></p><p>Status: <span class="status <?=status_class($u['operational_status'])?>"><?=e($u['operational_status'])?></span></p><p>Meter: <?=number_format($u['current_meter'],0,',','.')?> <?=e($u['meter_type'])?></p><p>Service berikut: <?=e($u['next_service_date']??'-')?> / <?=e((string)($u['next_service_meter']??'-'))?></p></main></body></html>
